import { createRequire } from "node:module";
import { writeFileSync } from "node:fs";
const require = createRequire("/home/mvhenten/development/stallion/package.json");
const { chromium, devices } = require("playwright");
const base = process.argv[2] ?? "https://stallion.matthijs-f49.workers.dev";
const tag = process.argv[3] ?? "before";
const paths = (process.argv[4] ?? `/,/b/default,/b/default-2,/b/fresh-${Math.random().toString(36).slice(2, 8)}`).split(",");
const browser = await chromium.launch({ headless: true });
const out = {};
for (const path of paths) {
  const ctx = await browser.newContext({ ...devices["Galaxy Tab S9"] });
  const page = await ctx.newPage();
  const log = { console: [], pageerrors: [], failed: [], ws: [], navigations: [] };
  page.on("console", (m) => { if (["error", "warning"].includes(m.type())) log.console.push(`${m.type()}: ${m.text()}`); });
  page.on("pageerror", (e) => log.pageerrors.push(String(e)));
  page.on("requestfailed", (r) => log.failed.push(`${r.url()} ${r.failure()?.errorText}`));
  page.on("response", (r) => { if (r.status() >= 400) log.failed.push(`${r.status()} ${r.url()}`); });
  page.on("framenavigated", (f) => { if (f === page.mainFrame()) log.navigations.push(f.url()); });
  page.on("websocket", (ws) => {
    const w = { url: ws.url(), received: 0, sent: 0, close: false, errors: [] };
    log.ws.push(w);
    ws.on("framereceived", () => w.received++);
    ws.on("framesent", () => w.sent++);
    ws.on("close", () => { w.close = true; });
    ws.on("socketerror", (e) => w.errors.push(String(e)));
  });
  const t0 = Date.now();
  const resp = await page.goto(base + path, { waitUntil: "commit", timeout: 30000 }).catch((e) => ({ err: String(e) }));
  log.status = resp?.status?.() ?? resp?.err;
  await page.waitForTimeout(8000);
  const name = `${tag}${path.replace(/\//g, "_")}.png`;
  await page.screenshot({ path: name, timeout: 15000 }).catch((e) => log.pageerrors.push(`screenshot: ${e}`));
  log.shot = name;
  log.finalUrl = page.url();
  log.text = await page.evaluate(() => document.body.innerText).catch((e) => `evaluate failed: ${e}`);
  log.ms = Date.now() - t0;
  out[path] = log;
  await ctx.close();
}
await browser.close();
writeFileSync(`${tag}.json`, JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));
EOF
