cd ~/development/stallion-worktrees/defaultfix && grep -n "BOARD_KEY" packages/client-sync/src/board.ts | head -2 && node - <<'EOF'
const fs = require("fs");
const f = "packages/client-sync/src/sync.test.ts";
let s = fs.readFileSync(f, "utf8");
s = s.replace(`import { openBoard, type StallionBoard } from "./index";`, `import { type BoardError, HANDSHAKE_FAILURES_REPORTED, openBoard, type StallionBoard } from "./index";`);
s = s.replace(`    backoff: { initialMs: 5, maxMs: 20 },
  });
  board.setView(VIEW, 1);`, `    backoff: { initialMs: 5, maxMs: 20 },
    onError: () => {},
  });
  board.setView(VIEW, 1);`);
s = s.replace(`test("offline edits replay after reconnect"`, `test("a board id the server rejects reports an error instead of connecting", async () => {
  const errors: BoardError[] = [];
  const attempts: string[] = [];
  const board = openBoard("wss://host", "default,", {
    connect: (url, handlers) => {
      attempts.push(url);
      return new TestServer().connect(url, handlers);
    },
    cache: { name: \`sync-test-\${databases++}\` },
    onError: (error) => errors.push(error),
  });
  boards.push(board);
  expect(attempts).toEqual([]);
  expect(board.status).toBe("Closed");
  expect(errors.map((error) => error.reason)).toEqual([
    'board id "default," is not valid: use 1 to 64 letters, digits, "-" or "_"',
  ]);
});

test("a server that keeps refusing the websocket handshake surfaces an error", async () => {
  const server = new TestServer();
  server.goOffline();
  const errors: BoardError[] = [];
  const board = openBoard("wss://host", "board", {
    connect: server.connect,
    cache: { name: \`sync-test-\${databases++}\` },
    backoff: { initialMs: 1, maxMs: 2 },
    onError: (error) => errors.push(error),
  });
  boards.push(board);
  await until(() => errors.length > 0, "the handshake failure report");
  expect(errors[0]?.reason).toBe(
    \`the server refused the board connection wss://host/api/boards/board/ws \${HANDSHAKE_FAILURES_REPORTED} times in a row; still retrying\`,
  );
});

test("offline edits replay after reconnect"`);
fs.writeFileSync(f, s);
EOF
