import { execFileSync } from "node:child_process";
const sha = process.argv[2]; const end = Date.now() + 15 * 60_000;
const nap = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
while (Date.now() < end) {
  let runs = [];
  try { runs = JSON.parse(execFileSync("gh", ["run", "list", "--repo", "mvhenten/stallion", "--workflow", "deploy.yml", "--limit", "1", "--json", "status,conclusion,headSha"], { encoding: "utf8" })); }
  catch (e) { console.log("gh error:", String(e.stderr ?? e).slice(0, 200)); nap(60_000); continue; }
  const r = runs[0];
  if (r?.headSha === sha && r.status === "completed") { console.log(JSON.stringify(r)); process.exit(0); }
  nap(30_000);
}
console.log("timed out"); 
EOF
